                        "new": ans["value"], "model": model, "label": f"row total/{t['row']}"})
        if t["kind"] == "grand":
            out.append({"entity": ("total", page, bid, "grand", ""), "old": self._total(page, bid, "grand", ""),
                        "new": ans["value"], "model": model, "label": "grand total"})
        return out

